UPDATE user_login UL join user_detail UD ON UL.USER_ID = UD.USER_ID
SET UL.USER_PASSWORD = #{encodePw}
WHERE UL.LOGIN_ID = #{findPwDto.loginId} AND UD.USER_EMAIL = #{findPwDto.email}

UPDATE user_login UL JOIN user_detail UD ON UL.USER_ID = UD.USER_ID
SET UD.USER_NAME = #{memberEditDto.changeName}, UD.USER_NICKNAME=#{memberEditDto.changeNickname}, 
UD.USER_TEL =#{memberEditDto.changeTel}, UD.USER_ZIPCODE=#{memberEditDto.changeZipcode}, UD.USER_ADDR=#{memberEditDto.changeFullAddr}
WHERE UL.LOGIN_ID = #{memberDto.login_id}
